html:
.cv-dl-heading {
  text-align: center;
  font-size: 20px;
  font-weight: 800;
  margin: 4px 0 14px 0;
  letter-spacing: 0.3px;
}
.cv-dl-heading-bracket {
  color: #818cf8;
  font-weight: 800;
}
.cv-dl-heading-text {
  background: linear-gradient(90deg, #22d3ee, #60a5fa, #a855f7);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.cv-dl-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 16px 10px 18px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: #0b0c10;
  border-radius: 10px;
}
.cv-dl-card:last-child {
  border-bottom: none;
}
.cv-dl-meta {
  font-size: 13.5px;
  font-weight: 800;
  margin-bottom: 12px;
  line-height: 1.4;
  word-break: break-word;
}
.cv-dl-part-1 { color: #f59e0b; }
.cv-dl-part-2 { color: #ffffff; }
.cv-dl-part-3 { color: #ec4899; }
.cv-dl-sep { color: #94a3b8; margin: 0 5px; font-weight: 700; }
.cv-dl-now-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 225px;
  max-width: 100%;
  padding: 11px 22px;
  border-radius: 10px;
  background: linear-gradient(90deg, #06b6d4 0%, #3b82f6 45%, #9333ea 100%);
  border: 1px solid rgba(165, 243, 252, 0.38);
  box-shadow: 0 4px 18px rgba(59, 130, 246, 0.35);
  color: #ffffff;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.6px;
  cursor: pointer;
  transition: transform 0.15s ease, opacity 0.15s ease;
}
.cv-dl-now-btn:active {
  transform: scale(0.96);
  opacity: 0.92;
}

